await page.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
await page.screenshot({path: '/tmp/language-desktop.png', fullPage: true});
await page.getByRole('radio', {name: 'EN', exact: true}).check();
await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
assert.equal(await page.locator('.language-options input[value=\"en\"]').isChecked(), true);
await page.locator('.language-options input[value=\"en\"]').focus();
await page.keyboard.press('ArrowRight');
await page.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
for (const width of [320, 375, 768]) {
