}
await page.setViewportSize({width: 375, height: 900});
await page.screenshot({path: '"'/tmp/language-mobile.png', fullPage: true});
await page.evaluate(() => localStorage.setItem('app-language', 'fr'));
await page.reload();
await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
await context.close();

const russianContext = await browser.newContext({locale: 'ru-RU'});
const russianPage = await russianContext.newPage();
await russianPage.goto('http://localhost:5174');
await russianPage.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
